SELECT setting_value
FROM policy_settings
WHERE code = #{code}

SELECT FROM gallery_photos g LEFT JOIN users u ON u.user_id = g.user_id WHERE g.semester_label = #{semester}
AND g.state IN ('normal', 'hidden') AND g.state = 'normal'
ORDER BY g.sort_order ASC, g.photo_id DESC

mapper.update:
UPDATE gallery_photos
SET state = 'deleted'
WHERE photo_id = #{photoId}
  AND user_id = #{userId}
  AND state = 'normal'

UPDATE gallery_photos
SET state = #{to}
WHERE photo_id = #{photoId}
  AND state = #{from}
